sp_angular_provider.script:
function DHApiFactory($http) {
  class DHApiInstance {
    constructor(version = "") {
      this.version = version;
    }

    #buildUrl(endpoint) {
      const vPart = this.version ? '/' + this.version : "";
      return '/api/x_mukl_dh' + vPart + '/dh/' + endpoint;
    }

    #handleActionError(e) {
      var errorMessage =
        "An unexpected error occurred while executing the action";
      if (e.data && e.data.error && e.data.error.message) {
        errorMessage = e.data.error.message;
        if (e.data.error.detail) {
          errorMessage += " - " + e.data.error.detail;
        }
      }
      throw new Error(errorMessage);
    }

    getDexScores() {
      return $http({
        method: "GET",
        url: this.#buildUrl("dex-score"),
        cache: true,
      }).then((r) => r.data);
    }

    getDeviceMetrics() {
      let url = new URL(
        this.#buildUrl("device-metrics"),
        window.location.origin
      );

      return $http({
        method: "GET",
        url: url.toString(),
        cache: true,
      });
    }

    executeRemoteAction(action_id, asset_id) {
      return $http({
        method: "POST",
        url: this.#buildUrl("exec-action") + '/' + action_id + '/' + asset_id,
      })
        .then((r) => r.data)
        .catch((e) => this.#handleActionError(e));
    }

    executeActionServerScript(action_id, asset_id) {
      return $http({
        method: "POST",
        url: this.#buildUrl("exec-action-server-script") + '/' + action_id + '/' + asset_id,
      })
        .then((r) => r.data)
        .catch((e) => this.#handleActionError(e));
    }
  }

  return (version) => new DHApiInstance(version);
}
